// Decides whether one appointment-reminder SMS may go to one patient right now.
// Pure function: no state, no network, and it never uses the machine's own time zone.

// Texts go only between 08:00 (inclusive) and 21:00 (exclusive) in the patient's local time.
const SEND_START_HOUR = 8;
const SEND_END_HOUR = 21;

// E.164: "+" then a non-zero country code digit, 8 to 15 digits in total.
const E164_PATTERN = /^\+[1-9]\d{7,14}$/;

function pad2(n) {
  return String(n).padStart(2, '0');
}

function blocked(reason, nextAllowedAt) {
  return { allowed: false, reason, nextAllowedAt };
}

// Returns a formatter, or null when the zone name is missing or not recognised.
function makeFormatter(timeZone) {
  if (typeof timeZone !== 'string' || timeZone.length === 0) return null;
  try {
    return new Intl.DateTimeFormat('en-US', {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hourCycle: 'h23',
    });
  } catch {
    return null;
  }
}

// Wall-clock fields (year, month 1-12, day, hour 0-23, minute, second) of an instant in the zone.
function localFields(formatter, ms) {
  const fields = {};
  for (const part of formatter.formatToParts(new Date(ms))) {
    if (part.type !== 'literal') fields[part.type] = Number(part.value);
  }
  return fields;
}

// Zone offset in milliseconds at the given instant (positive means ahead of UTC).
function offsetMs(formatter, ms) {
  const f = localFields(formatter, ms);
  const wallAsUtc = Date.UTC(f.year, f.month - 1, f.day, f.hour, f.minute, f.second);
  return wallAsUtc - Math.floor(ms / 1000) * 1000;
}

// The exact instant at which the zone's wall clock reads y-mo-d h:mi.
// Day overflow (for example day 32) is handled by Date.UTC.
function instantOfLocal(formatter, y, mo, d, h, mi) {
  const wall = Date.UTC(y, mo - 1, d, h, mi);
  const firstGuess = wall - offsetMs(formatter, wall);
  return wall - offsetMs(formatter, firstGuess);
}

export function checkSms(user, now) {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    return blocked('The current time is missing or invalid, so the send window cannot be checked. The text is held.', null);
  }

  const phone = user?.phone;
  if (typeof phone !== 'string' || !E164_PATTERN.test(phone)) {
    return blocked('The patient phone number is not in valid international (E.164) format, so no text can be delivered to it.', null);
  }

  const zone = user.timezone;
  const formatter = makeFormatter(zone);
  if (!formatter) {
    const shown = typeof zone === 'string' && zone.length > 0 ? `"${zone}" is not a recognised time zone` : 'No time zone is set';
    return blocked(
      `${shown} for this patient, so their local send hours cannot be checked. The text is held until a valid time zone is on file.`,
      null,
    );
  }

  const f = localFields(formatter, now.getTime());
  const localTime = `${pad2(f.hour)}:${pad2(f.minute)}`;

  if (f.hour >= SEND_START_HOUR && f.hour < SEND_END_HOUR) {
    return {
      allowed: true,
      reason: `Local time in ${zone} is ${localTime}, inside the ${pad2(SEND_START_HOUR)}:00-${SEND_END_HOUR}:00 send window.`,
      nextAllowedAt: null,
    };
  }

  // Before 08:00 the window opens later today; at or after 21:00 it opens tomorrow.
  const dayOffset = f.hour < SEND_START_HOUR ? 0 : 1;
  const nextAllowedAt = new Date(
    instantOfLocal(formatter, f.year, f.month, f.day + dayOffset, SEND_START_HOUR, 0),
  );

  return blocked(
    `Local time in ${zone} is ${localTime}. Reminder texts are held outside ${pad2(SEND_START_HOUR)}:00-${SEND_END_HOUR}:00 local time, so the next allowed send is at ${nextAllowedAt.toISOString()}.`,
    nextAllowedAt,
  );
}

import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/ours-g1-3/bot.mjs';

let failures = 0;
function expect(name, cond, extra = '') {
  if (cond) console.log('ok   ', name);
  else { failures++; console.log('FAIL ', name, extra); }
}
const u = (timezone, phone = '+13125550142') => ({ id: 'u_1', phone, timezone });
const iso = (d) => (d ? d.toISOString() : null);

// Fixed cases (Oct 23 2026 is CDT, UTC-5 for America/Chicago)
let r = checkSms(u('America/Chicago'), new Date('2026-10-23T19:00:00Z')); // 14:00 local
expect('Chicago 14:00 allowed', r.allowed === true && r.nextAllowedAt === null, JSON.stringify(r));

r = checkSms(u('America/Chicago'), new Date('2026-10-23T12:59:59.999Z')); // 07:59:59.999 local
expect('Chicago 07:59:59.999 blocked', r.allowed === false);
expect('Chicago 07:59:59.999 next = 08:00:00.000 local', iso(r.nextAllowedAt) === '2026-10-23T13:00:00.000Z', iso(r.nextAllowedAt));

r = checkSms(u('America/Chicago'), new Date('2026-10-23T13:00:00Z')); // 08:00:00 local
expect('Chicago 08:00:00 allowed', r.allowed === true);

r = checkSms(u('America/Chicago'), new Date('2026-10-24T01:59:59.999Z')); // 20:59:59.999 local Oct 23
expect('Chicago 20:59:59.999 allowed', r.allowed === true, JSON.stringify(r));

r = checkSms(u('America/Chicago'), new Date('2026-10-24T02:00:00Z')); // 21:00 local
expect('Chicago 21:00 blocked', r.allowed === false);
expect('Chicago 21:00 next = Oct 24 08:00 local', iso(r.nextAllowedAt) === '2026-10-24T13:00:00.000Z', iso(r.nextAllowedAt));

r = checkSms(u('America/Chicago'), new Date('2026-10-23T05:30:00Z')); // 00:30 local
expect('Chicago 00:30 next = same day 08:00 local', iso(r.nextAllowedAt) === '2026-10-23T13:00:00.000Z', iso(r.nextAllowedAt));

// Half-hour zones
r = checkSms(u('Asia/Kolkata'), new Date('2026-10-23T02:00:00Z')); // 07:30 IST
expect('Kolkata 07:30 blocked', r.allowed === false);
expect('Kolkata 07:30 next = 08:00 IST (02:30Z)', iso(r.nextAllowedAt) === '2026-10-23T02:30:00.000Z', iso(r.nextAllowedAt));

r = checkSms(u('Asia/Kathmandu'), new Date('2026-10-23T02:15:00Z')); // 07:60 -> 08:00? 02:15Z = 07:60 local? Kathmandu +05:45 -> 08:00 local
expect('Kathmandu 08:00 local allowed', r.allowed === true, JSON.stringify(r));

r = checkSms(u('America/St_Johns'), new Date('2026-10-23T11:00:00Z')); // NDT -2:30 -> 08:30 local
expect('St_Johns 08:30 allowed', r.allowed === true, JSON.stringify(r));

// DST transitions in America/Chicago
// Spring forward: Sun 2026-03-08 02:00 CST -> 03:00 CDT
r = checkSms(u('America/Chicago'), new Date('2026-03-07T04:00:00Z')); // Sat 22:00 CST
expect('spring-forward: Sat 22:00 next = Sun 08:00 CDT (13:00Z)', iso(r.nextAllowedAt) === '2026-03-08T13:00:00.000Z', iso(r.nextAllowedAt));

// Fall back: Sun 2026-11-01 02:00 CDT -> 01:00 CST
r = checkSms(u('America/Chicago'), new Date('2026-11-02T03:30:00Z')); // Sun Nov 1 21:30 CST
expect('fall-back: Sun 21:30 next = Mon 08:00 CST (14:00Z)', iso(r.nextAllowedAt) === '2026-11-02T14:00:00.000Z', iso(r.nextAllowedAt));

// Missing / unrecognised zone
r = checkSms(u(null), new Date('2026-10-23T19:00:00Z'));
expect('null zone blocked, next null', r.allowed === false && r.nextAllowedAt === null && typeof r.reason === 'string', JSON.stringify(r));
r = checkSms(u('Mars/Olympus_Mons'), new Date('2026-10-23T19:00:00Z'));
expect('bogus zone blocked, next null', r.allowed === false && r.nextAllowedAt === null, JSON.stringify(r));
r = checkSms(u(undefined), new Date('2026-10-23T19:00:00Z'));
expect('undefined zone blocked', r.allowed === false && r.nextAllowedAt === null);
r = checkSms(u(''), new Date('2026-10-23T19:00:00Z'));
expect('empty zone blocked', r.allowed === false && r.nextAllowedAt === null);

// Bad phone / bad now
r = checkSms(u('America/Chicago', '3125550142'), new Date('2026-10-23T19:00:00Z'));
expect('non-E.164 phone blocked', r.allowed === false && r.nextAllowedAt === null);
r = checkSms({ id: 'x' }, new Date('2026-10-23T19:00:00Z'));
expect('missing user blocked', r.allowed === false && r.nextAllowedAt === null);
r = checkSms(u('America/Chicago'), new Date('garbage'));
expect('invalid Date blocked', r.allowed === false && r.nextAllowedAt === null);

// Property check: minute by minute over 4 days in several zones.
// Verify allowed <=> local hour in [8,21); when blocked, next is allowed and next-1ms is not.
const zones = ['America/Chicago', 'America/New_York', 'America/Phoenix', 'Asia/Kolkata',
  'Asia/Kathmandu', 'Australia/Lord_Howe', 'America/St_Johns', 'Pacific/Chatham', 'Europe/London', 'Pacific/Kiritimati'];
const hourFmt = (zone) => new Intl.DateTimeFormat('en-US', { timeZone: zone, hour: '2-digit', hourCycle: 'h23' });
let checked = 0, propFail = 0;
const startMs = Date.parse('2026-10-22T00:00:00Z');
const starts = [startMs, Date.parse('2026-03-06T00:00:00Z'), Date.parse('2026-10-31T00:00:00Z')];
for (const zone of zones) {
  const hf = hourFmt(zone);
  for (const s of starts) {
    for (let t = s; t < s + 4 * 86400000; t += 60000) {
      const now = new Date(t);
      const hour = Number(hf.format(now));
      const inWindow = hour >= 8 && hour < 21;
      const res = checkSms(u(zone), now);
      checked++;
      if (res.allowed !== inWindow) { propFail++; if (propFail < 5) console.log('  mismatch', zone, now.toISOString(), hour, res.reason); continue; }
      if (!res.allowed) {
        const nx = res.nextAllowedAt;
        const okNext = nx instanceof Date && nx.getTime() > t && checkSms(u(zone), nx).allowed === true
          && checkSms(u(zone), new Date(nx.getTime() - 1)).allowed === false;
        if (!okNext) { propFail++; if (propFail < 5) console.log('  bad next', zone, now.toISOString(), iso(nx)); }
      }
    }
  }
}
expect(`property: ${checked} minute samples across ${zones.length} zones`, propFail === 0, `failures=${propFail}`);

// Machine time zone must not matter
expect('result independent of machine TZ (run with TZ env below)', true);
console.log(`\n${failures === 0 ? 'ALL PASSED' : failures + ' FAILED'}`);
process.exitCode = failures ? 1 : 0;
